def tree(cls):  # generic types: subclasses of a class (e.g. kinds of hat)
    return f'?item wdt:P279+ wd:{cls} .'
def kind(cls):  # instances or subclasses
    return f'?item (wdt:P31|wdt:P279)/wdt:P279* wd:{cls} .'

